package clipboard_test

import (
	"context"
	"testing"
	"time"

	"github.com/yeisme/clavis/pkg/core/clipboard"
	"github.com/yeisme/clavis/pkg/core/config"
)

func TestPrivacyFilterConcealedTypesAndBundles(t *testing.T) {
	cfg := config.DefaultClipboardConfig()
	filter := clipboard.NewPrivacyFilterFromConfig(cfg)

	concealedTypes := []string{
		"org.nspasteboard.ConcealedType",
		"org.nspasteboard.TransientType",
		"org.nspasteboard.AutoGeneratedType",
		"com.agilebits.onepassword",
		"com.agilebits.onepassword.item",
		"ExcludeClipboardContentFromMonitorProcessing",
		"CanIncludeInClipboardHistory",
		"x-kde-passwordManagerHint",
	}

	for _, typ := range concealedTypes {
		cand := clipboard.CaptureCandidate{
			Content:         "secret123",
			PasteboardTypes: []string{"public.utf8-plain-text", typ},
		}
		if filter.ShouldRecord(cand) {
			t.Fatalf("expected filter to ignore concealed type %q", typ)
		}
	}

	if filter.ShouldRecord(clipboard.CaptureCandidate{
		Content:        "secret",
		SourceBundleID: "com.1password.1password",
	}) {
		t.Fatal("expected filter to ignore excluded bundle ID")
	}

	if filter.ShouldRecord(clipboard.CaptureCandidate{Content: "   \t\n  "}) {
		t.Fatal("expected filter to ignore whitespace-only content")
	}

	if !filter.ShouldRecord(clipboard.CaptureCandidate{
		Content:         "hello clipboard",
		SourceBundleID:  "com.apple.Safari",
		PasteboardTypes: []string{"public.utf8-plain-text"},
	}) {
		t.Fatal("expected normal clipboard candidate to be recorded")
	}
}

func TestMemoryStoreDedupRepairsMediaMetadata(t *testing.T) {
	ctx := context.Background()
	store := clipboard.NewMemoryStore(clipboard.NewPrivacyFilter())
	first, ok, err := store.Record(ctx, clipboard.CaptureCandidate{
		Content: "",
		Media:   clipboard.Media{Kind: clipboard.KindImage, MediaPath: "/tmp/old.png", MediaMime: "image/png", BlobSHA: "blob-1", Width: 100},
	})
	if err != nil || !ok {
		t.Fatalf("record initial media: item=%+v ok=%v err=%v", first, ok, err)
	}
	if err := store.Pin(ctx, first.ID, true); err != nil {
		t.Fatalf("pin initial media: %v", err)
	}

	updated, ok, err := store.Record(ctx, clipboard.CaptureCandidate{
		Content:       "",
		SourceAppName: "Preview",
		Media:         clipboard.Media{Kind: clipboard.KindImage, MediaPath: "/tmp/new.png", MediaMime: "image/png", BlobSHA: "blob-1", Height: 200, ThumbPath: "/tmp/thumb.png", ByteSize: 42},
	})
	if err != nil || !ok || updated.ID != first.ID {
		t.Fatalf("dedup media: item=%+v ok=%v err=%v", updated, ok, err)
	}
	if !updated.IsPinned {
		t.Fatal("deduplication must preserve pinned state")
	}
	if updated.MediaPath != "/tmp/new.png" || updated.Width != 100 || updated.Height != 200 ||
		updated.ThumbPath != "/tmp/thumb.png" || updated.ByteSize != 42 {
		t.Fatalf("deduplication did not merge media metadata: %+v", updated.Media)
	}
	if updated.SourceAppName != "Preview" {
		t.Fatalf("expected source app repair, got %q", updated.SourceAppName)
	}
}

func TestMemoryStoreRejectsMediaWithoutBlobSHA(t *testing.T) {
	ctx := context.Background()
	store := clipboard.NewMemoryStore(clipboard.NewPrivacyFilter())
	item, ok, err := store.Record(ctx, clipboard.CaptureCandidate{
		Content: "same text",
		Media:   clipboard.Media{Kind: clipboard.KindImage},
	})
	if err == nil || ok || item != nil {
		t.Fatalf("expected malformed media rejection, item=%+v ok=%v err=%v", item, ok, err)
	}
	if textHash := (clipboard.CaptureCandidate{Content: "same text"}).DedupeHash(); textHash == (clipboard.CaptureCandidate{Content: "same text", Media: clipboard.Media{Kind: clipboard.KindImage}}).DedupeHash() {
		t.Fatal("malformed media must not use the text dedupe hash")
	}
}

func TestMemoryStoreLifecycle(t *testing.T) {
	ctx := context.Background()
	store := clipboard.NewMemoryStore(clipboard.NewPrivacyFilter())

	t0 := time.Now().UTC().Add(-40 * 24 * time.Hour)
	t1 := time.Now().UTC().Add(-2 * time.Hour)
	t2 := time.Now().UTC().Add(-1 * time.Hour)

	oldItem, ok, err := store.Record(ctx, clipboard.CaptureCandidate{
		Content:   "old item",
		Timestamp: t0,
	})
	if err != nil || !ok {
		t.Fatalf("record old failed: %v %v", ok, err)
	}

	item1, ok, err := store.Record(ctx, clipboard.CaptureCandidate{
		Content:       "first note",
		SourceAppName: "Notes",
		Timestamp:     t1,
	})
	if err != nil || !ok {
		t.Fatalf("record item1 failed: %v %v", ok, err)
	}

	item2, ok, err := store.Record(ctx, clipboard.CaptureCandidate{
		Content:       "second snippet",
		SourceAppName: "Safari",
		Timestamp:     t2,
	})
	if err != nil || !ok {
		t.Fatalf("record item2 failed: %v %v", ok, err)
	}

	// Deduplicate by content hash updates timestamp
	t3 := time.Now().UTC()
	dupItem, ok, err := store.Record(ctx, clipboard.CaptureCandidate{
		Content:       "first note",
		SourceAppName: "TextEdit",
		Timestamp:     t3,
	})
	if err != nil || !ok || dupItem.ID != item1.ID {
		t.Fatalf("expected deduplication to reuse ID %s, got %+v", item1.ID, dupItem)
	}

	// Pin item2 so it sorts first
	if err := store.Pin(ctx, item2.ID, true); err != nil {
		t.Fatalf("pin failed: %v", err)
	}

	recent, err := store.Recent(ctx, 10)
	if err != nil || len(recent) != 3 {
		t.Fatalf("expected 3 recent items, got %d (%v)", len(recent), err)
	}
	if recent[0].ID != item2.ID {
		t.Fatalf("expected pinned item2 first, got %s", recent[0].ID)
	}

	searchRes, err := store.Search(ctx, "snippet", 10)
	if err != nil || len(searchRes) != 1 || searchRes[0].ID != item2.ID {
		t.Fatalf("unexpected search results: %+v (%v)", searchRes, err)
	}

	pruned, err := store.PruneExpired(ctx, 30, 10)
	if err != nil || pruned != 1 {
		t.Fatalf("expected 1 pruned expired item, got %d (%v)", pruned, err)
	}
	recentAfterPrune, _ := store.Recent(ctx, 10)
	for _, it := range recentAfterPrune {
		if it.ID == oldItem.ID {
			t.Fatalf("expected oldItem to be pruned")
		}
	}

	if err := store.Delete(ctx, item1.ID); err != nil {
		t.Fatalf("delete failed: %v", err)
	}
	if err := store.Clear(ctx); err != nil {
		t.Fatalf("clear failed: %v", err)
	}
	empty, _ := store.Recent(ctx, 10)
	if len(empty) != 0 {
		t.Fatalf("expected empty after clear, got %d", len(empty))
	}
}
